var records = $input.all().map(function(i){ return i.json; });
var now = Date.now();
var windowMs = 24*60*60*1000;
var filtered = records.filter(function(r){
  var t = new Date(r.timestamp).getTime();
  return (now - t) <= windowMs;
});
filtered.sort(function(a,b){ return new Date(b.timestamp) - new Date(a.timestamp); });
var encoded = Buffer.from(JSON.stringify(filtered)).toString("base64");
var template = "<!DOCTYPE html>
<html lang="zh-Hant">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>兄弟大飯店 · 賓客回饋紀錄</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Noto+Serif+TC:wght@400;500;600;700&family=Noto+Sans+TC:wght@300;400;500&display=swap" rel="stylesheet">
<style>
  :root{
    --ink:#1C2A33;
    --ink-deep:#141F27;
    --ivory:#F3EFE6;
    --ivory-dim:#C9C2B4;
    --brass:#B08A4E;
    --brass-soft:#7C6640;
    --sage:#7FA083;
    --rust:#C07557;
    --stone:#9C978A;
    --line: rgba(176,138,78,0.28);
  }
  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;}
  body{
    background: radial-gradient(ellipse at top, #22323C 0%, var(--ink) 45%, var(--ink-deep) 100%);
    color: var(--ivory);
    font-family: "Noto Sans TC", sans-serif;
    min-height:100vh;
    padding: 56px 20px 90px;
  }
  .page{ max-width: 720px; margin: 0 auto; }
  header{
    display:flex; align-items:flex-end; justify-content:space-between; gap:20px;
    padding-bottom: 22px; border-bottom: 1px solid var(--line); margin-bottom: 6px;
  }
  .brand{ display:flex; align-items:center; gap:16px; }
  .mark{
    width:46px;height:46px; border:1px solid var(--brass); border-radius:50%;
    display:flex;align-items:center;justify-content:center;
    font-family:"Noto Serif TC", serif; font-weight:600; font-size:19px; color:var(--brass); flex-shrink:0;
  }
  h1{
    font-family:"Noto Serif TC", serif; font-weight:600; font-size: 25px;
    letter-spacing: 0.04em; margin:0 0 4px; color: var(--ivory);
  }
  .subtitle{ font-size: 13px; color: var(--ivory-dim); letter-spacing: 0.02em; }
  .clock{ text-align:right; font-variant-numeric: tabular-nums; flex-shrink:0; }
  .clock .now{ font-family:"Noto Serif TC", serif; font-size: 20px; color: var(--brass); }
  .clock .label{ font-size: 12px; color: var(--stone); margin-top: 3px; }
  .meta-row{
    display:flex; justify-content:space-between; align-items:center;
    font-size: 12.5px; color: var(--stone); padding: 16px 2px 34px;
  }
  .meta-row span.count{ color: var(--ivory-dim); }
  .ledger{ position:relative; padding-left: 84px; }
  .ledger::before{
    content:""; position:absolute; left: 60px; top: 6px; bottom: 6px; width: 1px;
    background: linear-gradient(to bottom, var(--brass) 0%, var(--line) 15%, var(--line) 85%, transparent 100%);
  }
  .entry{ position:relative; padding-bottom: 40px; }
  .entry:last-child{ padding-bottom: 4px; }
  .time-marker{ position:absolute; left: -84px; top: 2px; width: 60px; text-align:right; }
  .time-marker .clock-time{ font-family:"Noto Serif TC", serif; font-size: 15px; color: var(--ivory); font-variant-numeric: tabular-nums; }
  .time-marker .rel{ font-size: 11px; color: var(--stone); margin-top: 2px; }
  .dot{
    position:absolute; left: 56px; top: 6px; width: 9px;height:9px; border-radius:50%;
    background: var(--ink); border: 2px solid var(--brass);
  }
  .content{ padding-left: 4px; }
  .sentiment{
    font-size: 12px; letter-spacing: 0.03em; margin-bottom: 8px;
    display:inline-flex; align-items:center; gap: 6px;
  }
  .sentiment .sw{ width:6px;height:6px;border-radius:50%; }
  .sentiment.positive{ color: var(--sage); } .sentiment.positive .sw{ background: var(--sage); }
  .sentiment.negative{ color: var(--rust); } .sentiment.negative .sw{ background: var(--rust); }
  .sentiment.neutral{ color: var(--stone); } .sentiment.neutral .sw{ background: var(--stone); }
  .quote{
    font-family:"Noto Serif TC", serif; font-size: 16.5px; line-height: 1.75; color: var(--ivory);
    white-space: pre-line; margin: 0 0 16px;
  }
  .quote::before{ content:"「"; color: var(--brass); }
  .quote::after{ content:"」"; color: var(--brass); }
  .reply{ border-left: 2px solid var(--brass-soft); padding: 2px 0 2px 16px; }
  .reply .reply-label{ font-size: 11.5px; color: var(--brass); margin-bottom: 6px; letter-spacing: 0.02em; }
  .reply .reply-text{ font-size: 13.5px; line-height: 1.8; color: var(--ivory-dim); white-space: pre-line; font-weight:300; }
  .userId{ font-size: 11px; color: var(--brass-soft); margin-top: 12px; font-variant-numeric: tabular-nums; }
  .empty{ text-align:center; padding: 70px 20px; color: var(--stone); font-family:"Noto Serif TC", serif; font-size: 16px; }
  footer{ text-align:center; margin-top: 50px; font-size: 11.5px; color: var(--brass-soft); letter-spacing: 0.05em; }
  @media (max-width: 560px){
    .ledger{ padding-left: 58px; } .ledger::before{ left: 34px; } .dot{ left: 30px; }
    .time-marker{ left: -58px; width: 40px; }
    header{ flex-direction:column; align-items:flex-start; gap:10px; } .clock{ text-align:left; }
  }
  @media (prefers-reduced-motion: reduce){ *{ animation: none !important; transition: none !important; } }
</style>
</head>
<body>
  <div class="page">
    <header>
      <div class="brand">
        <div class="mark">兄</div>
        <div>
          <h1>兄弟大飯店</h1>
          <div class="subtitle">賓客回饋與客服對話紀錄</div>
        </div>
      </div>
      <div class="clock">
        <div class="now" id="nowClock">--:--</div>
        <div class="label" id="nowDate">----/--/--</div>
      </div>
    </header>
    <div class="meta-row">
      <span>過去 24 小時內的留言 · 依時間新到舊排列</span>
      <span class="count" id="countLabel">— 則</span>
    </div>
    <div class="ledger" id="ledger"></div>
    <div class="empty" id="emptyState" style="display:none;">過去 24 小時內尚無新留言</div>
  </div>
  <footer>兄弟大飯店 顧客服務團隊</footer>
  <script id="__data" type="application/json">__DATA_PLACEHOLDER__</script>
  <script>
    function base64ToUtf8(b64){
      var binary = atob(b64);
      var bytes = new Uint8Array(binary.length);
      for (var i = 0; i < binary.length; i++) { bytes[i] = binary.charCodeAt(i); }
      return new TextDecoder('utf-8').decode(bytes);
    }
    var RECORDS = JSON.parse(base64ToUtf8(document.getElementById('__data').textContent || 'W10='));

    function sentimentClass(s){
      if(!s) return "neutral";
      var v = String(s).toLowerCase();
      if(v.indexOf("pos") !== -1) return "positive";
      if(v.indexOf("neg") !== -1) return "negative";
      return "neutral";
    }
    function sentimentLabel(s){
      var cls = sentimentClass(s);
      if(cls === "positive") return "正面反饋";
      if(cls === "negative") return "負面反饋";
      return "中性留言";
    }
    function relTime(ms){
      var diff = Date.now() - ms;
      var min = Math.floor(diff/60000);
      if(min < 1) return "剛剛";
      if(min < 60) return min + " 分鐘前";
      var hr = Math.floor(min/60);
      if(hr < 24) return hr + " 小時前";
      return Math.floor(hr/24) + " 天前";
    }
    function formatClock(d){
      return d.toLocaleTimeString('zh-TW', {hour:'2-digit', minute:'2-digit', hour12:false});
    }
    function escapeHtml(str){
      var div = document.createElement('div');
      div.textContent = str || "";
      return div.innerHTML;
    }

    function render(){
      var now = Date.now();
      var windowMs = 24*60*60*1000;
      var items = RECORDS
        .map(function(r){ return Object.assign({}, r, { t: new Date(r.timestamp).getTime() }); })
        .filter(function(r){ return (now - r.t) <= windowMs; })
        .sort(function(a,b){ return b.t - a.t; });

      var ledger = document.getElementById('ledger');
      var empty = document.getElementById('emptyState');
      var countLabel = document.getElementById('countLabel');
      ledger.innerHTML = "";
      countLabel.textContent = items.length + " 則";

      if(items.length === 0){
        empty.style.display = "block";
        ledger.style.display = "none";
        return;
      }
      empty.style.display = "none";
      ledger.style.display = "block";

      items.forEach(function(item){
        var d = new Date(item.t);
        var cls = sentimentClass(item.sentiment);
        var entry = document.createElement('div');
        entry.className = "entry";
        entry.innerHTML =
          '<div class="time-marker">' +
            '<div class="clock-time">' + formatClock(d) + '</div>' +
            '<div class="rel">' + relTime(item.t) + '</div>' +
          '</div>' +
          '<div class="dot"></div>' +
          '<div class="content">' +
            '<div class="sentiment ' + cls + '"><span class="sw"></span>' + sentimentLabel(item.sentiment) + '</div>' +
            '<p class="quote">' + escapeHtml(item.customerMessage) + '</p>' +
            '<div class="reply">' +
              '<div class="reply-label">回覆內容</div>' +
              '<div class="reply-text">' + escapeHtml(item.botResponse) + '</div>' +
            '</div>' +
            '<div class="userId">賓客識別碼　' + escapeHtml(item.userId) + '</div>' +
          '</div>';
        ledger.appendChild(entry);
      });
    }

    function tickClock(){
      var now = new Date();
      document.getElementById('nowClock').textContent = formatClock(now);
      document.getElementById('nowDate').textContent = now.toLocaleDateString('zh-TW', {year:'numeric', month:'2-digit', day:'2-digit'});
    }

    render();
    tickClock();
    setInterval(tickClock, 1000);
    setInterval(render, 60000);
  </script>
</body>
</html>
";
var html = template.replace("__DATA_PLACEHOLDER__", encoded);
return [{ json: { html: html } }];
